// Pseudo-test using k6 with dynamic flag injection
import http from 'k6/http';
import { check, sleep } from 'k6';

export let options = {
  vus: 2000,
  duration: '5m',
};

export default function () {
  const tenantId = Math.floor(Math.random() * 100);
  const userId = Math.floor(Math.random() * 10000);
  const url = `https://api.example.com/api/v2/users/${userId}`;

  const params = {
    headers: {
      'X-Tenant-ID': tenantId.toString(),
      'X-Feature-Flags': `extendedProfile:${Math.random() > 0.5}`
    }
